'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isArray = require( '@stdlib/assert/is-array' );
var Legend = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Legend, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `properties` property', function test( t ) {
	var v;

	v = new Legend({
		'fill': 'colorScale'
	});
	t.strictEqual( hasOwnProp( v, 'properties' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'properties' ), true, 'returns expected value' );
	t.strictEqual( isArray( v.properties ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `properties` property which returns a list of enumerable properties', function test( t ) {
	var expected;
	var props;
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});
	props = legend.properties;

	t.strictEqual( isArray( props ), true, 'returns expected value' );

	expected = [
		'aria',
		'clipHeight',
		'columnPadding',
		'columns',
		'cornerRadius',
		'description',
		'direction',
		'encode',
		'fill',
		'fillColor',
		'format',
		'formatType',
		'gradientLength',
		'gradientOpacity',
		'gradientStrokeColor',
		'gradientStrokeWidth',
		'gradientThickness',
		'gridAlign',
		'labelAlign',
		'labelBaseline',
		'labelColor',
		'labelFont',
		'labelFontSize',
		'labelFontStyle',
		'labelFontWeight',
		'labelLimit',
		'labelOffset',
		'labelOpacity',
		'labelOverlap',
		'labelSeparation',
		'legendX',
		'legendY',
		'offset',
		'opacity',
		'orient',
		'padding',
		'rowPadding',
		'shape',
		'size',
		'stroke',
		'strokeColor',
		'strokeDash',
		'strokeWidth',
		'symbolDash',
		'symbolDashOffset',
		'symbolFillColor',
		'symbolLimit',
		'symbolOffset',
		'symbolOpacity',
		'symbolSize',
		'symbolStrokeColor',
		'symbolStrokeWidth',
		'symbolType',
		'tickCount',
		'tickMinStep',
		'title',
		'titleAlign',
		'titleAnchor',
		'titleBaseline',
		'titleColor',
		'titleFont',
		'titleFontSize',
		'titleFontStyle',
		'titleFontWeight',
		'titleLimit',
		'titleLineHeight',
		'titleOpacity',
		'titleOrient',
		'titlePadding',
		'type',
		'values',
		'zindex'
	];
	t.deepEqual( props, expected, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `properties` property which returns a new array on each access', function test( t ) {
	var props1;
	var props2;
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});
	props1 = legend.properties;
	props2 = legend.properties;

	t.notEqual( props1, props2, 'returns expected value' );
	t.deepEqual( props1, props2, 'returns expected value' );

	t.end();
});
